import{d,C as n,o as g,c as h,a3 as e,E as s,j as a,a as p}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"正易心法·第五章","description":"《正易心法》第五章——六十四卦无穷妙义尽在画中：蒙取次于艮、师取次于坤，卦序之次非私意，乃阴阳运动、血气流行的自然之理。","frontmatter":{"title":"正易心法·第五章","description":"《正易心法》第五章——六十四卦无穷妙义尽在画中：蒙取次于艮、师取次于坤，卦序之次非私意，乃阴阳运动、血气流行的自然之理。","category":"guide","aliases":["正易心法第五章","无穷妙义尽在画中","取次于"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-05.md","filePath":"yijing/zheng-yi-xin-fa/chapter-05.md","lastUpdated":1790647676000}'),c={name:"yijing/zheng-yi-xin-fa/chapter-05.md"},q=d({...c,setup(u){const i=[{id:"z5-01",label:"一、尽在画中",showLabel:!0,sentences:[["六十四卦，无穷妙义，",{text:"尽在画中",glossary:"jinzaiHua"},"，合为自然。"]],note:["六十四卦的无穷妙义，全部在卦画之中，合于自然之理。（这一句是本章的总纲，也是前四章理论的第一次具体落实——由「象为本」推到了「卦序也是象」。）"]},{id:"z5-02",label:"二、蒙取次于艮",showLabel:!0,sentences:[["无穷妙义，若蒙必",{text:"取次于",glossary:"quciyu"},"艮，师必取次于坤，是大有旨意也。"]],note:["所谓「无穷妙义」：比如蒙卦必然紧接在艮之后（蒙的上卦即艮），师卦必然紧接在坤之后（师的上卦即坤），这其中有深意。麻衣在这里把《序卦传》的文字逻辑，还原为卦画的结构逻辑——蒙之所以有「蒙」义，是因为上艮下坎：山止于外，险伏于内。"]},{id:"z5-03",label:"三、不止于卦辞",showLabel:!0,sentences:[["不止于贞丈人吉，童蒙求我之义。"]],note:["绝不止于「贞，丈人吉」（师卦卦辞）或「童蒙求我」（蒙卦卦辞）这些文字表面的意思。（卦辞只是对那个卦画状态的一句话描述，不是本义。要问的不是「为什么卦辞这么说」，而是「卦画本身是什么样子」。）"]},{id:"z5-04",label:"四、非是私意",showLabel:!0,sentences:[["合为自然，谓次艮、次坤，非是",{text:"私意",glossary:"siyi"},"，"]],note:["所谓「合为自然」，是说蒙次艮、师次坤这样的安排，并非出于人的主观安排。（「私意」与「自然」相对——卦序不是谁设计出来的，是卦画结构自己排出来的。）"]},{id:"z5-05",label:"五、皆自然之理",showLabel:!0,sentences:[["乃阴阳运动，血气流行，其所",{text:"施为",glossary:"shiwei"},"，皆自然之理也。"]],note:["而是阴阳运动、血气流行，它的运作方式都合于自然之理。（这一句几乎是第二章结尾「卦画凡以此顺此理而已」的原话重现。第二章说的是卦画本身是自然节律，本章说的是卦与卦之间的关系也是自然节律——不是重复，是深化。）"]}],o=[{id:"jinzaiHua",term:"尽在画中",pinyin:"jìn zài huà zhōng",meaning:"全部在卦画之中。呼应第三章「本无文字」。"},{id:"quciyu",term:"取次于",pinyin:"qǔ cì yú",meaning:"紧接排列于……之后。指卦序中的前后相邻关系，也含卦画结构上的关联（如蒙之上卦即艮）。"},{id:"siyi",term:"私意",pinyin:"sī yì",meaning:"个人主观意图。与「自然」相对，指人为安排。"},{id:"shiwei",term:"施为",pinyin:"shī wéi",meaning:"所作所为、运作方式。此处指卦序的排列运作。"}];return(b,t)=>{const r=n("DaoTextReading"),l=n("DaoKeywordCards");return g(),h("div",null,[t[0]||(t[0]=e(`<h1 id="正易心法·第五章" tabindex="-1">正易心法·第五章 <a class="header-anchor" href="#正易心法·第五章" aria-label="Permalink to &quot;正易心法·第五章&quot;">​</a></h1><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>本章把前四章的理论<strong>落实到具体卦例</strong>上，第一次用实例证明：<strong>卦序的排列，是卦画结构的自然结果，不是人为的文字逻辑。</strong></p><p>这是一个<strong>方法论示范</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>不要问：为什么蒙卦的卦辞说「童蒙求我」？</span></span>
<span class="line"><span>而要问：蒙卦的卦画结构是什么？</span></span>
<span class="line"><span>        上艮（止）下坎（险）→ 被山止住、陷于险中</span></span>
<span class="line"><span>        → 这就是「蒙」的真实状态</span></span>
<span class="line"><span>        → 卦辞只是对这个状态的文字描述，不是本义</span></span></code></pre></div><h2 id="为什么重要" tabindex="-1">为什么重要 <a class="header-anchor" href="#为什么重要" aria-label="Permalink to &quot;为什么重要&quot;">​</a></h2><p><strong>「取次于」的两层意思</strong>：</p><table tabindex="0"><thead><tr><th>层</th><th>含义</th></tr></thead><tbody><tr><td><strong>卦画结构</strong></td><td>蒙卦上卦是艮，故蒙与艮有直接的结构关联——蒙是艮的「展开」</td></tr><tr><td><strong>卦序逻辑</strong></td><td>相邻的卦往往有卦画上的内在联系，这种联系是阴阳消息的自然流动</td></tr></tbody></table><p><strong>呼应第二章</strong>——本章末句几乎是第二章结尾的原话重现：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第二章：「卦画凡以此顺此理而已。」   卦画是自然节律（总论）</span></span>
<span class="line"><span>第五章：「其所施为，皆自然之理也。」 卦序也是自然节律（具体到卦与卦的关系）</span></span></code></pre></div><p>这不是重复，而是<strong>螺旋深化</strong>。</p><h2 id="怎么读" tabindex="-1">怎么读 <a class="header-anchor" href="#怎么读" aria-label="Permalink to &quot;怎么读&quot;">​</a></h2><ol><li>先看<strong>蒙与艮</strong>、<strong>师与坤</strong>的结构关系（上卦相同）；</li><li>再把《序卦传》的说法（「物生必蒙」「讼必有众」）与麻衣的说法<strong>并读</strong>；</li><li>记住一句话：<strong>两者都在解释同一个事实，路径不同。</strong></li></ol><h2 id="核心内容要点" tabindex="-1">核心内容要点 <a class="header-anchor" href="#核心内容要点" aria-label="Permalink to &quot;核心内容要点&quot;">​</a></h2><ul><li><strong>尽在画中</strong>：六十四卦的妙义全在卦画。</li><li><strong>取次于</strong>：蒙取次于艮、师取次于坤——卦序由卦画结构决定。</li><li><strong>不止于卦辞</strong>：卦辞是截面，不是全体。</li><li><strong>非是私意</strong>：卦序非人为安排。</li><li><strong>皆自然之理</strong>：阴阳运动、血气流行，与第二章同一声口。</li></ul><h2 id="【原典层】原文" tabindex="-1">【原典层】原文 <a class="header-anchor" href="#【原典层】原文" aria-label="Permalink to &quot;【原典层】原文&quot;">​</a></h2>`,16)),s(r,{colophon:"无穷妙义 · 尽在画中 · 取次于艮坤 · 皆自然之理",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第五章原文",sections:i,glossary:o}),t[1]||(t[1]=a("blockquote",null,[a("p",null,"注：本页依所据底本录入，用字随底本，不作统一。")],-1)),t[2]||(t[2]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[p("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),s(l,{items:[{term:"取次于",pinyin:["qǔ","cì","yú"],meaning:"紧接排列于……之后。既指卦序中的相邻关系，也含卦画结构上的关联（蒙之上卦即艮）。"},{term:"私意",pinyin:["sī","yì"],meaning:"与「自然」相对，指人为安排。麻衣说卦序非私意，乃卦画结构自己排出来的。"},{term:"蒙 · 艮",pinyin:["méng","gèn"],meaning:"蒙☶☵（上艮下坎）：山止于外、险伏于内，正是蒙昧未开之象。故曰「蒙取次于艮」。"},{term:"师 · 坤",pinyin:["shī","kūn"],meaning:"师☷☵（上坤下坎）：大地包容、地中藏水，正是众聚之象。故曰「师取次于坤」。"}]}),t[3]||(t[3]=e('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一章在说什么" tabindex="-1">象：这一章在说什么 <a class="header-anchor" href="#象-这一章在说什么" aria-label="Permalink to &quot;象：这一章在说什么&quot;">​</a></h3><p>前四章是理论，本章是<strong>第一次方法论示范</strong>：不要问「为什么卦辞这么说」，而要问「卦画结构是什么」。</p><p><strong>核心命题：文辞是卦义的截面，卦画是卦义的全体。</strong></p><blockquote><p>就像用一张照片描述一个人——照片能捕捉某一瞬间，但人的全部生命不在照片里。<strong>卦辞是照片，卦画是活生生的人。</strong></p></blockquote><h3 id="理-为什么这样说" tabindex="-1">理：为什么这样说 <a class="header-anchor" href="#理-为什么这样说" aria-label="Permalink to &quot;理：为什么这样说&quot;">​</a></h3><p><strong>「取次于」的两层意思</strong>：</p><ul><li><strong>卦画结构层</strong>：蒙卦上卦是艮，故蒙是艮的「展开」；</li><li><strong>卦序逻辑层</strong>：相邻的卦有卦画上的内在联系，这是阴阳消息的自然流动。</li></ul><p><strong>与《序卦传》的对比</strong>——两者都在解释同一个事实（蒙卦的位置），但路径完全不同：</p><table tabindex="0"><thead><tr><th>比较点</th><th>《序卦传》</th><th>麻衣道者</th></tr></thead><tbody><tr><td>解释工具</td><td>文字义理推演</td><td>卦画结构分析</td></tr><tr><td>蒙卦的原因</td><td>「物生必蒙」（逻辑）</td><td>上艮下坎的卦画结构（象）</td></tr><tr><td>师卦的原因</td><td>「讼必有众」（逻辑）</td><td>上坤下坎的卦画结构（象）</td></tr><tr><td>卦序的本质</td><td>万物生长的哲学逻辑链</td><td>卦画结构的自然展开</td></tr></tbody></table><p><strong>两者并不矛盾</strong>——就像解释「水往低处流」：一个说「万物皆趋于安稳」，一个说「水的重力势能结构如此」。<strong>麻衣不是说《序卦传》错了，而是说：只读文字而不看卦画，就像只知道那句话，却不知道为什么。</strong></p><h3 id="用-今天怎么进入这一章" tabindex="-1">用：今天怎么进入这一章 <a class="header-anchor" href="#用-今天怎么进入这一章" aria-label="Permalink to &quot;用：今天怎么进入这一章&quot;">​</a></h3><ul><li>把蒙、师两卦的<strong>上下卦</strong>看清楚，再看它们的<strong>上卦</strong>分别是什么（艮、坤）；</li><li>与《序卦传》对读，体会「同一个事实，两套语言」；</li><li>记住这一句：<strong>「不要纠结于对错，这也是阴阳之理——我们应当透过象与理，找到后面的『神』。」</strong></li></ul><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>六十四卦的无穷妙义，全部在卦画之中，合于自然之理。</p><p>所谓「无穷妙义」：比如蒙卦必然紧接在艮之后，师卦必然紧接在坤之后——这其中大有旨意，绝不止于「贞，丈人吉」或「童蒙求我」这些文字表面的意思。</p><p>所谓「合为自然」：蒙次艮、师次坤这样的安排，并非出于人的主观意图，而是阴阳运动、血气流行——它的运作方式，都合于自然之理。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p><strong>一句话</strong>：第五章是前四章的第一次落地——<strong>卦序不是排出来的，是长出来的。</strong></p></blockquote><p>可以按这几条慢慢写：</p><ul><li><strong>「取次于」</strong>——蒙的上卦是艮、师的上卦是坤。我读卦时，注意过「这一卦的上卦，曾在哪一卦里出现过」吗？</li><li><strong>照片与活人的比喻</strong>——卦辞是照片，卦画是活人。<strong>我平时读卦，是在看照片，还是在看人？</strong></li><li><strong>与《序卦传》并读</strong>——不要急着判对错。<strong>「透过象与理，找寻后面的『神』」</strong>——这句话是你在思考里补的，我很认同：<strong>两套语言不是竞争关系，是同一个「神」的两种显影。</strong></li><li><strong>留给自己的问题</strong>：如果卦序是卦画结构自然展开的，那么<strong>六十四卦的排列顺序，能不能从卦画本身推出来？</strong>（这个问题，历代都有人尝试，答案莫衷一是。）</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/yijing/zheng-yi-xin-fa/">正易心法总览</a></li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-02">第二章 · 六画之设</a> — 「卦画凡以此顺此理而已」（本章是其具体化）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-04">第四章 · 《易》道不传</a> — 执辞忘象之弊（本章是「不执辞」的示范）</li><li><a href="/Dao/yijing/shi-yi/xu-gua-zhuan">序卦传</a> — 同为解释卦序：一以文字推演，一以卦画结构</li></ul>',23))])}}});export{y as __pageData,q as default};
